import { format, parseISO } from 'date-fns';

const date1 = new Date('2022-01-01');
const date2 = new Date('2024-03-20');

const diff = format(date1, "dd MMM yyyy") - format(date2, "dd MMM yyyy");
console.log(diff);
```

